#!/usr/bin/env python3
"""Read-only branch-to-main comparisons. Report evidence, never infer feature completion."""
import json
import hashlib
import os
import urllib.parse
import urllib.request
from pathlib import Path

def compare_rows(report, fetch, evidence=None):
    snapshot = report.get("snapshot") or {}
    branches = snapshot.get("branches") or {}
    default = report.get("default_branch")
    if not isinstance(branches, dict) or default not in branches:
        raise ValueError("Incomplete branch snapshot")
    rows = []
    for name, sha in sorted(branches.items()):
        if name == default:
            continue
        if not isinstance(sha, str) or len(sha) != 40:
            rows.append((name, "inconclusive: missing SHA", "", "", ""))
            continue
        path = "/repos/" + urllib.parse.quote(report["repository"], safe="/") + "/compare/" + urllib.parse.quote(default, safe="") + "..." + urllib.parse.quote(name, safe="")
        try:
            data = fetch(path)
            if not isinstance(data, dict):
                raise ValueError("Unexpected API result")
            status = data.get("status", "unknown")
            ahead = data.get("ahead_by", "?")
            behind = data.get("behind_by", "?")
            files = data.get("files", [])
            if not isinstance(files, list):
                raise ValueError("Missing files list")
            # GitHub compare returns a capped file list. Do not claim coverage at or near the cap.
            coverage = "partial/unknown" if len(files) >= 300 or ahead == "?" else "API-reported"
            if evidence is not None:
                evidence[name] = {
                    "head_sha": sha,
                    "status": status,
                    "files_complete": len(files) < 300 and ahead != "?",
                    "paths": sorted({item["filename"] for item in files
                                     if isinstance(item, dict) and isinstance(item.get("filename"), str)}),
                    "patch_sha256": {item["filename"]: hashlib.sha256(item["patch"].encode("utf-8")).hexdigest()
                                     for item in files if isinstance(item, dict)
                                     and isinstance(item.get("filename"), str)
                                     and isinstance(item.get("patch"), str)
                                     and item["patch"]},
                    "patch_absence": [item["filename"] for item in files if isinstance(item, dict)
                                      and isinstance(item.get("filename"), str)
                                      and not isinstance(item.get("patch"), str)]
                }
            sample = ", ".join(str(f.get("filename", "")) for f in files[:8] if isinstance(f, dict))
            rows.append((name, str(status), str(ahead), str(behind), coverage + ": " + sample))
        except (ValueError, KeyError, OSError) as error:
            rows.append((name, "inconclusive: " + type(error).__name__, "", "", ""))
    return rows

def find_shared_paths(evidence):
    """Potential review leads, not a statement of duplicated implementations."""
    if not isinstance(evidence, dict):
        raise ValueError("Missing evidence")
    by_file = {}
    for branch, info in evidence.items():
        if not isinstance(info, dict):
            continue
        for path in info.get("paths", []):
            # Documentation and CI infrastructure overlap frequently; ignore those paths.
            if path.startswith(("docs/", ".github/", "tests/")) or path.endswith((".md", ".lock")):
                continue
            by_file.setdefault(path, []).append(branch)
    return {path: sorted(names) for path, names in sorted(by_file.items()) if len(names) > 1}


def find_equal_patches(evidence):
    """Exact patch equality only. Hashes are evidence, not a duplicate-feature decision."""
    matches = {}
    groups = {}
    for branch, info in sorted(evidence.items()):
        if not isinstance(info, dict):
            continue
        hashes = info.get("patch_sha256", {})
        if not isinstance(hashes, dict):
            continue
        for path, digest in hashes.items():
            if not isinstance(digest, str) or len(digest) != 64:
                continue
            if path.startswith(("docs/", ".github/", "tests/")) or path.endswith((".md", ".lock")):
                continue
            groups.setdefault((path, digest), []).append(branch)
    for (path, digest), branches in sorted(groups.items()):
        if len(branches) >= 2:
            matches.setdefault(path, []).append({"patch_sha256": digest, "branches": sorted(branches)})
    return matches


def render_equal_patches(matches):
    lines = ["# Identical comparison patches (review only)", "",
             "Matching GitHub compare patch text SHA-256 indicates identical API-returned diff hunks",
             "for one file at the time of this snapshot. This is NOT proof of duplicate features,",
             "commits, or merge safety. Missing/truncated patches cannot be assessed.", "",
             "| Changed path | Matching branch heads | Patch SHA-256 |", "|---|---|---|"]
    for path, groups in sorted(matches.items()):
        for group in groups:
            safe_path = path.replace("|", "&#124;").replace("\\n", " ")
            names = ", ".join(branch.replace("|", "&#124;").replace("\\n", " ") for branch in group["branches"])
            lines.append("| " + safe_path + " | " + names + " | " + group["patch_sha256"] + " |")
    if not matches:
        lines.append("| None observed in available patches | — | — |")
    return "\\n".join(lines) + "\\n"


def render_shared_paths(overlaps, evidence):
    lines = ["# Shared changed-file candidates (review only)", "",
             "Multiple branches changing the same path does NOT establish duplicate functionality.",
             "Check actual patches, merged PR history, and the development ledger.", "",
             "| File | Branches | Evidence coverage |", "|---|---|---|"]
    for path, names in overlaps.items():
        coverage = "partial/unknown" if any(
            not evidence[name].get("files_complete", False) for name in names) else "API-reported"
        safe_path = path.replace("|", "&#124;").replace("\n", " ")
        safe_names = ", ".join(name.replace("|", "&#124;").replace("\n", " ") for name in names)
        lines.append(f"| {safe_path} | {safe_names} | {coverage} |")
    if not overlaps:
        lines.extend(["", "No shared changed paths found in the available API evidence; "
                      "this does not prove absence of duplicated work."])
    return "\n".join(lines) + "\n"


def render(rows):
    lines = ["# Branch-to-main evidence (read-only)", "",
             "This is GitHub compare metadata, not proof that a feature is missing, complete, or safe to merge.",
             "Review full diff, closed PRs, and ledger before taking action.", "",
             "| Branch | Compare status | Ahead | Behind | File evidence |",
             "|---|---|---:|---:|---|"]
    for fields in rows:
        escaped = [str(value).replace("|", "&#124;").replace("\n", " ") for value in fields]
        lines.append("| " + " | ".join(escaped) + " |")
    return "\n".join(lines) + "\n"

def main():
    report = json.loads(Path("inventory-output/report.json").read_text(encoding="utf-8"))
    repo = report["repository"]
    token = os.environ["GITHUB_TOKEN"]
    def fetch(path):
        req = urllib.request.Request("https://api.github.com" + path, headers={
            "Authorization": "Bearer " + token,
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "branch-to-main-inventory"})
        with urllib.request.urlopen(req, timeout=20) as response:
            return json.load(response)
    evidence = {}
    rows = compare_rows(report, fetch, evidence=evidence)
    Path("inventory-output/branch-comparison.md").write_text(render(rows), encoding="utf-8")
    overlaps = find_shared_paths(evidence)
    equal_patches = find_equal_patches(evidence)
    Path("inventory-output/branch-file-evidence.json").write_text(
        json.dumps({"branches": evidence, "shared_paths": overlaps, "equal_patches": equal_patches}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8")
    Path("inventory-output/shared-file-review.md").write_text(
        render_shared_paths(overlaps, evidence), encoding="utf-8")
    Path("inventory-output/equal-patch-review.md").write_text(
        render_equal_patches(equal_patches), encoding="utf-8")
    print("Recorded comparisons for " + str(len(rows)) + " branches in " + repo)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Prioritize human review of branch evidence without deciding implementation status."""
import json
from pathlib import Path

def prioritize(handoff, evidence):
    items = handoff.get("assignments")
    shared = evidence.get("shared_paths")
    equal = evidence.get("equal_patches")
    if not isinstance(items, list) or not isinstance(shared, dict) or not isinstance(equal, dict):
        raise ValueError("Incomplete handoff or patch evidence")
    result = []
    for row in items:
        if not isinstance(row, dict) or not isinstance(row.get("branch"), str):
            raise ValueError("Malformed handoff entry")
        branch = row["branch"]
        exact_paths = sorted(path for path, groups in equal.items()
                             if isinstance(groups, list) and any(
                                 isinstance(group, dict) and branch in group.get("branches", [])
                                 for group in groups))
        reasons = []
        if exact_paths:
            reasons.append("identical_api_patch_hints")
        if not row.get("file_evidence_complete"):
            reasons.append("file_evidence_incomplete")
        if not row.get("explicit_case_ids"):
            reasons.append("no_explicit_case_reference")
        if not row.get("pr_numbers"):
            reasons.append("no_historical_pr_reference")
        overlap = sorted(path for path, branches in shared.items()
                         if isinstance(branches, list) and branch in branches)
        if overlap:
            reasons.append("shared_file_paths")
        priority = ("P1_review" if exact_paths or not row.get("file_evidence_complete")
                    else "P2_review" if overlap or not row.get("explicit_case_ids") or not row.get("pr_numbers")
                    else "P3_review")
        result.append({
            "branch": branch, "priority": priority, "reasons": reasons,
            "explicit_case_ids": row.get("explicit_case_ids", []),
            "historical_pr_numbers": row.get("pr_numbers", []),
            "equal_patch_paths": exact_paths[:10],
            "shared_file_paths": overlap[:10],
            "next_action": "Review actual main diff, closed/merged PRs, and existing case notes",
            "auto_applied": False
        })
    return sorted(result, key=lambda x: (x["priority"], x["branch"]))

def render(rows):
    lines = ["# Branch inventory human review queue", "",
             "P1/P2/P3 rank *review urgency*, NOT feature completeness, duplicate status, or merge readiness.",
             "An exact API patch match is only a lead. Unknown API coverage is not a no-change result.", "",
             "| Priority | Branch | Existing case | PR history | Evidence hints |",
             "|---|---|---|---|---|"]
    for item in rows:
        safe = lambda value: str(value).replace("|", "&#124;").replace("\n", " ")
        lines.append("| " + " | ".join([
            item["priority"], safe(item["branch"]),
            ", ".join(item["explicit_case_ids"]) or "unmatched",
            ", ".join("#" + str(n) for n in item["historical_pr_numbers"]) or "unmatched",
            ", ".join(item["reasons"]) or "routine review",
        ]) + " |")
    lines += ["", "Do not create or close cases, alter ledger status, merge, or delete based on this queue.", ""]
    return "\n".join(lines)

def main():
    output = Path("inventory-output")
    handoff = json.loads((output / "branch-case-handoff.json").read_text(encoding="utf-8"))
    evidence = json.loads((output / "branch-file-evidence.json").read_text(encoding="utf-8"))
    rows = prioritize(handoff, evidence)
    (output / "branch-review-queue.json").write_text(
        json.dumps({"candidates": rows, "auto_applied": False}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8")
    (output / "branch-review-queue.md").write_text(render(rows), encoding="utf-8")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Evidence-backed Japanese history. Standard library; never executes project code.

Extends development_work_history.py and its inventory snapshot. No LLM/API billing,
DB, application routes, notification calls or deployment mutations.
"""
import argparse
import datetime as dt
import hashlib
import html
import json
import os
from pathlib import Path
import re
import subprocess
import urllib.error
import urllib.parse
import urllib.request

VERSION = 3
SAFE_SUFFIXES = {'.py','.ts','.tsx','.js','.mjs','.cjs','.json','.md','.yml','.yaml','.sql','.css','.sh'}
SECRET_PATH = re.compile(r'(^|[/._-])(env|secret|credential|private[-_]?key|token)([./_-]|$)', re.I)
REDACTIONS = [r'(?i)\b(?:sk-proj-|sk-|ghp_|github_pat_|ghs_|sb_secret_)[A-Za-z0-9_\-]{15,}',
              r'eyJ[A-Za-z0-9_-]{15,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}',
              r'(?i)(?:bearer\s+)[A-Za-z0-9._-]{15,}',
              r'(?i)((?:password|api[_-]?key|access[_-]?token|refresh[_-]?token|client[_-]?secret)\s*[=:]\s*)[\'\"][^\'\"\n]{8,}[\'\"]']

def clean(value):
    text = str(value or '')
    for pattern in REDACTIONS:
        text = re.sub(pattern, '[REDACTED]', text)
    return text

def digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True).encode()).hexdigest()

def write(path, value):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(value, encoding='utf-8')

def dump(path, value):
    write(path, json.dumps(value, ensure_ascii=False, indent=2)+'\n')

class Missing(Exception): pass
class API:
    def __init__(self, repo, cache=None, offline=False):
        self.repo, self.cache, self.offline = repo, Path(cache) if cache else None, offline
        self.pending, self.calls = set(), 0
    def get(self, path):
        path = '/repos/'+self.repo+path
        file = self.cache/(hashlib.sha256(path.encode()).hexdigest()+'.json') if self.cache else None
        if file and file.exists():
            data = json.loads(file.read_text())
            if isinstance(data,dict) and '_http_error' in data: raise RuntimeError('HTTP '+str(data['_http_error']))
            return data
        if self.offline:
            self.pending.add(path); raise Missing(path)
        self.calls += 1
        if self.calls > int(os.environ.get('HISTORY_MAX_API_CALLS','3500')):
            raise RuntimeError('API request budget exceeded')
        headers={'Accept':'application/vnd.github+json','User-Agent':'development-history-evidence'}
        if os.environ.get('GITHUB_TOKEN'): headers['Authorization']='Bearer '+os.environ['GITHUB_TOKEN']
        request=urllib.request.Request('https://api.github.com'+path,headers=headers)
        try:
            with urllib.request.urlopen(request,timeout=30) as response: data=json.load(response)
        except urllib.error.HTTPError as error:
            # Do not log request headers, response body, or credentials.
            raise RuntimeError('GitHub HTTP '+str(error.code)) from None
        if file: dump(file,data)
        return data
    def pages(self,path,field=None):
        result=[]
        for page in range(1,101):
            data=self.get(path+('&' if '?' in path else '?')+'per_page=100&page='+str(page))
            batch=data[field] if field else data
            if not isinstance(batch,list): raise ValueError('Unexpected paginated response')
            result.extend(batch)
            if len(batch)<100: return result
        raise RuntimeError('Pagination exceeded; refusing incomplete history')

def git(*args):
    return subprocess.check_output(['git',*args],text=True,stderr=subprocess.DEVNULL)

def ensure_commit(sha):
    """PR metadata can advance after checkout/fetch (e.g. the ledger bot)."""
    if not isinstance(sha,str) or not re.fullmatch(r'[0-9a-f]{40}',sha):
        raise ValueError('Invalid commit SHA')
    try: git('cat-file','-e',sha+'^{commit}')
    except subprocess.CalledProcessError:
        # Fetch the exact observed object, never a moving ref or arbitrary URL.
        git('fetch','--quiet','--no-tags','origin',sha)
        git('cat-file','-e',sha+'^{commit}')

def source(sha,path):
    if SECRET_PATH.search(path) or Path(path).suffix not in SAFE_SUFFIXES:
        return {'path':path,'coverage':'対象外（秘密情報候補／非テキスト）'}
    try:
        size=int(git('cat-file','-s',sha+':'+path))
        if size>120000: return {'path':path,'coverage':'サイズ上限120KB・原本リンク参照'}
        text=clean(git('show',sha+':'+path))
        return {'path':path,'coverage':'全文' if len(text)<=18000 else '先頭18000文字・原本リンク参照',
                'text':text[:18000], 'sha256':hashlib.sha256(text.encode()).hexdigest()}
    except (subprocess.CalledProcessError,ValueError):
        return {'path':path,'coverage':'削除済み／取得不能・差分参照'}

TOPICS = [
 ('雨量・全国検知',r'rain|jma|stride|pixel|forecast|雨|降水|画素|全国', '雨量判定・予測・全国候補抽出に関する変更'),
 ('記憶・会話',r'memory|chat|conversation|relationship|記憶|会話|関係性', '会話や記憶・関係性を扱う処理の変更'),
 ('ラウンジ・画面',r'lounge|video|avatar|animation|ラウンジ|演出', 'ラウンジ・映像・画面演出に関する変更'),
 ('通知・配信',r'notif|push|jaspic|gmail|配信|通知|メール', '通知・メール配信とその運用に関する変更'),
 ('開発管理',r'inventory|ledger|approval|promotion|history|棚卸|台帳|承認|履歴', '開発資産の把握・引継ぎ・レビューを支援する変更'),
 ('認証・安全性',r'auth|rls|security|認証|安全', '認証・アクセス制御に関する変更'),
 ('画面・表示',r'page|ui|display|map|画面|表示|地図', '画面表示や操作に関する変更')]

def describe(title,paths):
    haystack=title+' '+' '.join(paths)
    topics=[(name,purpose) for name,pattern,purpose in TOPICS if re.search(pattern,haystack,re.I)]
    return ([x[0] for x in topics] or ['その他の開発'], '／'.join(x[1] for x in topics) or '変更対象ファイルに関する開発。具体的な目的は原文・差分を確認')

def symbols(text):
    return sorted(set(re.findall(r'(?:function\s+|def\s+|class\s+|(?:export\s+)?(?:async\s+)?(?:const|let)\s+)([A-Za-z_$][\w$]*)',text)))[:60]

def observed_runs(runs):
    return [{'name':clean(r.get('name')), 'head_sha':r.get('head_sha'), 'conclusion':r.get('conclusion'),
             'status':r.get('status'), 'url':r.get('html_url'), 'id':r['id'], 'updated_at':r.get('updated_at'),
             'event':r.get('event')} for r in runs]

def local_files(base,head):
    rows=[]
    for line in git('diff','--no-renames','--numstat',base+'...'+head).splitlines():
        added,removed,path=line.split('\t',2)
        patch='' if SECRET_PATH.search(path) or Path(path).suffix not in SAFE_SUFFIXES else clean(git('diff','--no-ext-diff','--no-renames',base+'...'+head,'--',path))
        if len(patch)>60000: patch=patch[:60000]+'\n[差分は60000文字で打切り・原本参照]'
        status='modified'
        try: git('cat-file','-e',head+':'+path)
        except subprocess.CalledProcessError: status='removed'
        rows.append({'filename':path,'status':status,'additions':int(added) if added.isdigit() else 0,'deletions':int(removed) if removed.isdigit() else 0,'patch':patch})
    return rows

def local_commits(base,head,repo):
    rows=[]
    for sha in git('rev-list','--reverse',base+'..'+head).splitlines():
        rows.append({'sha':sha,'commit':{'message':git('show','-s','--format=%B',sha)},'html_url':'https://github.com/'+repo+'/commit/'+sha})
    return rows

def code_facts(files):
    facts=[]
    patterns=[('HTTP要求',r'\bfetch\s*\(|urlopen\(|requests\.(get|post)'),
              ('DB・ストレージ操作の呼出し',r'\.(rpc|from|insert|upsert|update|delete)\s*\('),
              ('テストの期待値・条件',r'\b(assert|expect|test|it|describe)[.(\s]'),
              ('条件分岐・閾値',r'\bif\s*\(|\bif .+:|\b(?:const|let) [A-Z_]+\s*='),
              ('SQL定義・権限',r'(?i)\b(create|alter|grant|revoke|drop)\s+(table|function|policy|index|select|execute)'),
              ('関数・クラス定義',r'\b(function|def|class)\s+\w+'),
              ('実行する検証コマンド',r'run:|npm (test|run)|python3? .*test')]
    for f in files:
        added=[l[1:] for l in f.get('patch','').splitlines() if l.startswith('+') and not l.startswith('+++')]
        found=0
        for line in added:
            for label,pattern in patterns:
                if re.search(pattern,line):
                    facts.append({'file':f['path'],'kind':label,'expression':clean(line.strip())[:350],'url':f['url']})
                    found+=1;break
            if found>=12:break
    return facts

def collect_pr(api,num,meta,run_index,curated):
    pr=api.get('/pulls/'+num)
    ensure_commit(pr['base']['sha']); ensure_commit(pr['head']['sha'])
    files=local_files(pr['base']['sha'],pr['head']['sha'])
    commits=local_commits(pr['base']['sha'],pr['head']['sha'],api.repo)
    comments=api.pages('/issues/'+num+'/comments')
    reviews=api.pages('/pulls/'+num+'/reviews')
    head=pr['head']['sha']; merge=pr.get('merge_commit_sha') if pr.get('merged_at') else None
    main_status='未統合／未確認'
    candidate=merge or head
    try:
        subprocess.check_call(['git','merge-base','--is-ancestor',candidate,api.main_sha],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        main_status='mainに祖先コミットとして存在（機能受入・本番は別）'
    except subprocess.CalledProcessError:
        main_status='main祖先として未確認（squash・同等実装は別途照合）'
    runs=list(run_index.get(head,[]))+list(run_index.get(merge,[]))
    # Historical head runs can fall outside the current global run window.
    historical=api.pages('/actions/runs?head_sha='+head, 'workflow_runs')
    runs={r['id']:r for r in runs+historical}
    paths=[f['filename'] for f in files]
    topic,purpose=describe(pr['title'],paths)
    texts=[]; evidence=[]
    for f in files:
        path=f['filename']
        safe=not SECRET_PATH.search(path) and Path(path).suffix in SAFE_SUFFIXES
        patch=clean(f.get('patch','')) if safe else ''
        item={'path':path,'status':f['status'],'additions':f['additions'],'deletions':f['deletions'],
              'patch':patch, 'patch_coverage':'git merge-baseから対象HEADへの差分（最大60000文字）' if patch else '差分なし／対象外',
              'url':'https://github.com/'+api.repo+'/blob/'+head+'/'+urllib.parse.quote(path)}
        src=source(head,path); item['source']=src
        texts.append(patch+'\n'+src.get('text','')); evidence.append(item)
    # Related docs are not restricted to files touched by the PR.
    related=[]
    corpus=(pr.get('body') or '')+'\n'+'\n'.join(texts)
    for path in sorted(set(re.findall(r'(?:docs|tests|scripts)/[\w./-]+\.(?:md|json|py|ts)',corpus)))[:40]:
        if path not in paths: related.append(source(head,path))
    curated_entry=curated.get('prs',{}).get(num,{})
    return {'id':'pr-'+num,'number':int(num),'title':clean(pr['title']), 'topics':topic,'purpose':purpose,
            'purpose_basis':'変更パスと表題による分類（意味の確定には原文を確認）',
            'body':clean(pr.get('body')), 'snapshot_head':meta.get('head'), 'snapshot_consistent':not meta.get('head') or meta.get('head')==head, 'head':head,'base':pr['base']['sha'],'base_ref':pr['base']['ref'],
            'head_ref':pr['head']['ref'],'state':'merged' if pr.get('merged_at') else pr['state'],
            'main_status':main_status,'draft':pr.get('draft',False),'merged_at':pr.get('merged_at'),'merge_commit_sha':merge,'updated_at':pr['updated_at'],
            'code_facts':code_facts(evidence),'files':evidence,'file_count':len(files),'reported_file_count':pr.get('changed_files'),
            'commits':[{'sha':c['sha'],'message':clean(c['commit']['message']),'url':c['html_url']} for c in commits],
            'comments':[{'body':clean(c.get('body')),'url':c['html_url']} for c in comments if c.get('user',{}).get('type')!='Bot'],
            'reviews':[{'state':c['state'],'body':clean(c.get('body')),'url':c['html_url']} for c in reviews],
            'runs':observed_runs(list(runs.values())), 'symbols':symbols('\n'.join(texts)),
            'related_sources':related,'curated':curated_entry,
            'implementation':'変更差分を取得。実装の受入完了は未認定',
            'verification':'Actionsの成否は実行単位の事実。製品の受入検証とは別',
            'production':'未確認（main統合／Vercelプレビューから推定しない）',
            'remaining':'受入条件・未解決事項をPR本文、レビュー、台帳と照合',
            'next':'類似コード・既存結論を確認し、未解決条件だけを次の作業にする'}

def branch_case(name,sha,base,repo,prs):
    linked=[p['number'] for p in prs.values() if p.get('head_ref')==name]
    try:
        raw=git('diff','--name-status',base+'...'+sha)
        paths=[line.split('\t')[-1] for line in raw.splitlines()]
        commits=git('log','--format=%H %s',base+'..'+sha).splitlines()
        files=[]
        same_head=any(p.get('head')==sha for p in prs.values())
        for path in paths:
            if same_head:
                files.append({'path':path,'source':{'coverage':'同一HEADのPR案件に原文収録'},'url':'https://github.com/'+repo+'/blob/'+sha+'/'+urllib.parse.quote(path)})
                continue
            src=source(sha,path)
            patch='' if SECRET_PATH.search(path) else clean(git('diff','--no-ext-diff',base+'...'+sha,'--',path))[:18000]
            files.append({'path':path,'source':src,'patch':patch,'url':'https://github.com/'+repo+'/blob/'+sha+'/'+urllib.parse.quote(path)})
        return {'id':'branch-'+digest(name)[:16],'title':clean(name),'head':sha,'head_ref':name,'linked_prs':linked,
                'files':files,'commits':clean('\n'.join(commits)),'topics':describe(name,paths)[0],
                'state':'ブランチ差分（PR関連あり）' if linked else 'PR未関連のブランチ差分',
                'production':'未確認','implementation':'mainとの差分を収録。差分ゼロも記録',
                'next':'関連PR・mainとの同等実装を照合。ブランチの存在だけで未完成扱いしない'}
    except subprocess.CalledProcessError:
        return {'id':'branch-'+digest(name)[:16],'title':clean(name),'head':sha,'files':[], 'linked_prs':linked,
                'state':'取得不能','topics':['未調査'],'production':'未確認','next':'リモート参照を取得して再解析'}

def search(cases,query):
    tokens=[t.lower() for t in re.split(r'\s+',query.strip()) if t]
    if not tokens: return []
    results=[]
    for c in cases.values():
        text=json.dumps(c,ensure_ascii=False).lower()
        hits=sum(t in text for t in tokens)
        if hits == len(tokens):
            priority=hits+3*sum(t in c.get('title','').lower() for t in tokens)+2*sum(t in json.dumps(c.get('curated',{}),ensure_ascii=False).lower() for t in tokens)
            results.append((priority,c['id'],c))
    return [c for _,_,c in sorted(results,key=lambda x:(-x[0],x[1]))]

def md(value):
    return html.escape(clean(value)).replace('|','&#124;')

def render_case(c,repo):
    num=c.get('number'); lines=['# '+md(c['title']),'']
    if num: lines+=['[PR原本](https://github.com/'+repo+'/pull/'+str(num)+')','']
    for label,key in [('目的','purpose'),('実装状態','implementation'),('検証の扱い','verification'),('PR状態','state'),('main統合','main_status'),('本番反映','production'),('残課題','remaining'),('次の作業','next')]:
        lines+=['**'+label+'：** '+md(c.get(key,'未確認')),'']
    if c.get('linked_prs'):
        lines+=['関連PR：'+', '.join('[#'+str(n)+'](https://github.com/'+repo+'/pull/'+str(n)+')' for n in c['linked_prs']),'']
    if c.get('collected_at'): lines+=['根拠取得日時 (UTC)：'+c['collected_at'],'']
    if c.get('curated'):
        lines+=['## 日本語で確認した成果','',md(c['curated'].get('summary')),'',md(c['curated'].get('conclusion')),'']
        for link in c['curated'].get('evidence',[]): lines+=['- [根拠]('+link+')']
    lines+=['','## 実際の変更処理（コードから抽出）','',md('、'.join(c.get('symbols',[])) or '差分・ソースを参照'),'']
    for fact in c.get('code_facts',[]):
        lines+=['- '+md(fact['kind'])+'：`'+md(fact['expression']).replace('`','&#96;')+'`（['+md(fact['file'])+']('+fact['url']+')）']
    for f in c.get('files',[]):
        lines+=['- ['+md(f['path'])+']('+f['url']+')：'+md(f.get('source',{}).get('coverage','差分参照'))]
    lines+=['','## 検証実行の事実','', '| ワークフロー | 結果 | 対象SHA |','| --- | --- | --- |']
    for r in c.get('runs',[]):
        lines+=['| ['+md(r.get('name'))+']('+str(r.get('url'))+') | '+md(r.get('conclusion') or r.get('status'))+' | '+md(r.get('head_sha'))+' |']
    if not c.get('runs'): lines+=['| 実行証拠未取得 | 未確認 | — |']
    lines+=['','## 当時の説明・結論（原文。作者の主張と実測を区別）','', '```text',clean(c.get('body','')).replace('```','~~~'),'```']
    for item in c.get('comments',[])+c.get('reviews',[]):
        if item.get('body'): lines+=['','[記録元]('+item['url']+')','```text',clean(item['body']).replace('```','~~~'),'```']
    lines+=['','## ソース・テスト・資料の抜粋（実行はしない）','']
    for f in c.get('files',[]):
        text=f.get('patch') or f.get('source',{}).get('text','')
        if text: lines+=['### '+md(f['path']),'','```text',text.replace('```','~~~'),'```','']
    for f in c.get('related_sources',[]):
        if f.get('text'): lines+=['### 関連資料 '+md(f['path']),'','```text',f['text'].replace('```','~~~'),'```','']
    return '\n'.join(lines)+'\n'

def duplicate_candidates(cases):
    by_path={}
    for key,c in cases.items():
        for f in c.get('files',[]):
            p=f['path']
            if p.startswith(('docs/','.github/','tests/')) or p.endswith(('.md','.json','.lock')): continue
            by_path.setdefault(p,set()).add(key)
    return {p:sorted(ids) for p,ids in sorted(by_path.items()) if len(ids)>1}

def render_output(state,out,repo):
    cases=state['cases']; out=Path(out); out.mkdir(parents=True,exist_ok=True)
    lines=['# 日本語開発履歴・着手前検索','', 'コード・差分・コミット・PR議論・Actions実行を同じ案件にまとめた履歴です。分類は自動抽出、重要結論は日本語確認記録です。',
           '', '実装の存在、検証の成功、main統合、本番反映を別々に扱います。未確認を完成扱いしません。',
           '', '更新 (UTC): '+state['generated_at'], '', '## 全案件','', '| 案件 | 分野・日本語作業内容 | 統合状態 | 本番 |','| --- | --- | --- | --- |']
    for key,c in sorted(cases.items()):
        write(out/'cases'/(key+'.md'),render_case(c,repo))
        summary=c.get('curated',{}).get('summary') or c.get('purpose') or 'mainとのソース差分を収録・関連PRを照合'
        lines+=['| ['+md(c['title'])+'](cases/'+key+'.md) | '+md('・'.join(c.get('topics',[]))+'：'+summary)+' | '+md(c.get('main_status','未確認'))+' | 未確認 |']
    lines+=['','## 既存コードの重複候補','', '同じファイルを変更した案件です。同一機能と断定せず、結論と差分を先に照合してください。','']
    duplicates=duplicate_candidates(cases)
    for path,ids in duplicates.items():
        lines+=['- '+md(path)+'：'+', '.join('['+key+'](cases/'+key+'.md)' for key in ids)]
    lines+=['','## 更新と制約','', '- 過去版は revisions/ に追記保存。state.json は次回の差分解析に利用。',
            '- ソースは120KB以下のテキストを最大18000文字ずつ取得。差分省略、取得失敗は原本確認が必要。',

#!/usr/bin/env python3
"""Generate read-only inventory change candidates from the prior successful artifact."""
import io
import json
import os
import urllib.parse
import urllib.error
import urllib.request
import urllib.error
import zipfile
from pathlib import Path

API = "https://api.github.com"
REPO = os.environ.get("GITHUB_REPOSITORY", "")
TOKEN = os.environ.get("GITHUB_TOKEN", "")
CURRENT_RUN = str(os.environ.get("GITHUB_RUN_ID", ""))

class SafeRedirect(urllib.request.HTTPRedirectHandler):
    """Do not forward GitHub bearer tokens to external artifact storage."""
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        redirected = super().redirect_request(req, fp, code, msg, headers, newurl)
        if redirected is not None and urllib.parse.urlsplit(newurl).hostname != urllib.parse.urlsplit(req.full_url).hostname:
            redirected.remove_header("Authorization")
            redirected.unredirected_hdrs.pop("Authorization", None)
        return redirected

OPENER = urllib.request.build_opener(SafeRedirect)

def api(path, binary=False):
    req = urllib.request.Request(API + path, headers={
        "Authorization": "Bearer " + TOKEN,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "development-inventory-delta-readonly",
    })
    try:
        response = OPENER.open(req, timeout=30)
    except urllib.error.HTTPError as error:
        # Expose the failed endpoint *path*, never signed query parameters or tokens.
        location = urllib.parse.urlsplit(error.url)
        raise RuntimeError("GitHub artifact lookup HTTP " + str(error.code) +
                           " at " + location.hostname + location.path) from error
    with response:
        return response.read() if binary else json.load(response)

def previous_snapshot():
    repo = urllib.parse.quote(REPO, safe="/")
    runs = api("/repos/" + repo + "/actions/workflows/development-inventory.yml/runs?status=success&per_page=30")
    for run in runs.get("workflow_runs", []):
        if str(run["id"]) == CURRENT_RUN or run["event"] not in ("schedule", "workflow_dispatch"):
            continue
        artifacts = api("/repos/" + repo + "/actions/runs/" + str(run["id"]) + "/artifacts?per_page=100")
        for item in artifacts.get("artifacts", []):
            if item["name"] != "development-inventory" or item.get("expired"):
                continue
            archive = api("/repos/" + repo + "/actions/artifacts/" + str(item["id"]) + "/zip", binary=True)
            with zipfile.ZipFile(io.BytesIO(archive)) as z:
                with z.open("report.json") as f:
                    previous = json.load(f)
            if previous.get("repository") == REPO and "snapshot" in previous:
                return previous, run["id"]
    return None, None

def compare(previous, current):
    changes = []
    for group in ("branches", "prs", "issues"):
        before = previous.get("snapshot", {}).get(group, {})
        after = current["snapshot"][group]
        for key in sorted(set(before) | set(after)):
            if key not in before:
                kind = "added"
            elif key not in after:
                kind = "absent_from_snapshot"
            elif before[key] != after[key]:
                kind = "changed"
            else:
                continue
            changes.append({"type": group, "id": key, "change": kind,
                            "before": before.get(key), "after": after.get(key)})
    return changes


def classify_candidates(changes, index_text):
    """Conservative review-only matching; PR files are evidence, never proof."""
    import re
    rows = re.findall(r"^\|\s*([AM]-\d+)\s*\|\s*([^|]+)\|", index_text, re.M)
    suggestions = []
    for change in changes:
        identifier = str(change["id"])
        details = change.get("after") or change.get("before") or {}
        # Branch snapshots contain SHA strings, while PR snapshots contain dicts.
        # Never treat a branch SHA as PR metadata.
        if not isinstance(details, dict):
            details = {}
        metadata = " ".join(str(details.get(k, "")) for k in ("title", "body", "head_ref"))
        filenames = []
        file_status = "not_applicable"
        if change["type"] == "prs" and identifier.isdigit() and REPO:
            try:
                path = "/repos/" + urllib.parse.quote(REPO, safe="/") + "/pulls/" + identifier + "/files?per_page=100"
                files = api(path)
                filenames = [item["filename"] for item in files if "filename" in item]
                file_status = "partial_first_100" if len(files) == 100 else "complete"
            except (RuntimeError, urllib.error.URLError, ValueError, KeyError):
                file_status = "unavailable"
        text = (identifier + " " + metadata + " " + " ".join(filenames)).lower()
        tokens = set(re.findall(r"[a-z0-9]{4,}", text.replace("_", "-")))
        tokens.update(re.findall(r"[\u3040-\u30ff\u4e00-\u9fff]{2,}", text))
        matches = []
        for case_id, title in rows:
            title_tokens = set(re.findall(r"[a-z0-9]{4,}", title.lower()))
            title_tokens.update(re.findall(r"[\u3040-\u30ff\u4e00-\u9fff]{2,}", title))
            if tokens & title_tokens:
                matches.append(case_id)
        # Generic infrastructure PRs are not forced into product work items.
        infrastructure = any(x in text for x in ("development_inventory", "development-inventory", "inventory-triage"))
        if infrastructure:
            matches = []
        suggestions.append({
            "source_type": change["type"], "source_id": identifier,
            "change": change["change"], "candidate_case_ids": matches,
            "classification": ("automation_maintenance" if infrastructure else
                               "possible_existing" if matches else "needs_review"),
            "ledger_action": "review_only", "proposed_status": None,
            "evidence": "PR metadata and changed file names; unverified token hints",
            "file_evidence": {"status": file_status, "paths": filenames[:100]}
        })
    return suggestions

def write_triage(output, result):
    index_path = Path("docs/DEVELOPMENT_OPERATIONS_INDEX.md")
    index_text = index_path.read_text(encoding="utf-8") if index_path.exists() else ""
    suggestions = classify_candidates(result["changes"], index_text) if result["status"] == "compared" else []
    payload = {"status": result["status"], "previous_run_id": result["previous_run_id"],
               "suggestions": suggestions, "auto_applied": False}
    (output / "triage-proposals.json").write_text(
        json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    lines = ["# 台帳更新案（承認待ち・自動反映なし）", "",
             "比較状態: " + result["status"], "",
             "候補は照合用のヒントです。完了・未完了・削除可否は自動判定しません。", ""]
    if result["status"] != "compared":
        lines.append("比較未完了のため更新案を作成していません。")
    for item in suggestions:
        linked = ", ".join(item["candidate_case_ids"]) or "未特定"
        lines.extend(["- " + item["source_type"] + " " + item["source_id"] +
                      " (" + item["change"] + ")",
                      "  - 関連候補: " + linked + "（未検証）",
                      "  - 台帳変更案: 照合後に人が判断（状態変更なし）"])
    (output / "ledger-review-proposals.md").write_text("\n".join(lines) + "\n", encoding="utf-8")

def main():
    output = Path("inventory-output")
    current = json.loads((output / "report.json").read_text(encoding="utf-8"))
    error_note = None
    try:
        previous, run_id = previous_snapshot()
    except (RuntimeError, urllib.error.HTTPError, urllib.error.URLError, zipfile.BadZipFile, KeyError, ValueError) as error:
        # Never discard today's complete inventory because a prior artifact cannot be read.
        # Explicitly report the comparison failure; do NOT claim zero changes.
        previous, run_id = None, None
        error_note = "Previous report unavailable: " + type(error).__name__
        if isinstance(error, urllib.error.HTTPError):
            error_note += " (HTTP " + str(error.code) + ")"
        if isinstance(error, RuntimeError):
            error_note += " (" + str(error) + ")"
    if error_note:
        result = {"status": "comparison_unavailable", "previous_run_id": None, "changes": [],
                  "note": error_note + "; delta NOT checked. Current inventory saved."}
    elif previous is None:
        result = {"status": "baseline_only", "previous_run_id": None, "changes": [],
                  "note": "No prior compatible successful artifact; do not infer no changes."}
    else:
        result = {"status": "compared", "previous_run_id": run_id,
                  "changes": compare(previous, current),
                  "note": "Candidates only. No automatic ledger status or completion decisions."}
    (output / "delta.json").write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    lines = ["# Development inventory change candidates", "",
             "Status: " + result["status"],
             "Previous run: " + str(run_id or "none"),
             "Candidates: " + str(len(result["changes"])), "",
             result["note"], "",
             "**Read-only suggestions; verify main, PR history and ledger before updating.**", ""]
    for c in result["changes"]:
        lines.append("- " + c["type"] + " `" + c["id"].replace("`", "") + "`: " + c["change"])
    (output / "ledger-update-candidates.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    write_triage(output, result)
    print("\n".join(lines))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Conservative PR promotion classifier. Never merges, approves, or deploys."""
import argparse
import json
from pathlib import PurePosixPath

HIGH_RISK_PREFIXES = (
    "src/", "app/", "pages/", "api/", "supabase/", "database/",
    "migrations/", "functions/", "lib/", "server/", "public/",
)
HIGH_RISK_EXACT = {
    "package.json", "package-lock.json", "pnpm-lock.yaml",
    "vercel.json", "next.config.js", "next.config.ts",
    ".env", ".env.production",
}
POLICY_PREFIXES = (".github/", "scripts/",)
FACTS_LEDGER = "docs/DEVELOPMENT_LEDGER.md"

def classify(paths, *, draft=False, complete=True):
    """Fail closed: file names are insufficient proof of safe content."""
    paths = list(paths)
    if draft:
        return {"decision": "hold_draft", "reason": "Draft PR; never promote"}
    if not complete or not paths:
        return {"decision": "hold_incomplete", "reason": "Missing/incomplete file evidence"}
    for path in paths:
        if not isinstance(path, str) or not path or path.startswith("/") or "\\" in path:
            return {"decision": "hold_invalid", "reason": "Invalid changed path"}
        if ".." in PurePosixPath(path).parts:
            return {"decision": "hold_invalid", "reason": "Traversal in changed path"}
    if any(p.startswith(HIGH_RISK_PREFIXES) or p in HIGH_RISK_EXACT
           or p.startswith(".env") for p in paths):
        return {"decision": "owner_approval_required", "reason": "Production or app behavior may change"}
    if any(p.startswith(POLICY_PREFIXES) for p in paths):
        return {"decision": "maintainer_review_required", "reason": "Automation or policy changes cannot self-approve"}
    if FACTS_LEDGER in paths:
        return {"decision": "maintainer_review_required", "reason": "Ledger changes require managed-section diff verification"}
    return {"decision": "maintainer_review_required", "reason": "No content-level allow rule has been verified"}

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--files-json", required=True, help="JSON list of all changed paths")
    parser.add_argument("--draft", action="store_true")
    parser.add_argument("--incomplete", action="store_true")
    args = parser.parse_args()
    with open(args.files_json, encoding="utf-8") as f:
        paths = json.load(f)
    if not isinstance(paths, list):
        raise ValueError("Expected JSON list of paths")
    print(json.dumps(classify(paths, draft=args.draft, complete=not args.incomplete), ensure_ascii=False))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Classify a PR using trusted main-branch policy and GitHub API metadata. Read-only."""
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

try:
    from scripts.pr_promotion_policy import classify
except ModuleNotFoundError:
    from pr_promotion_policy import classify


def fetch_json(path):
    req = urllib.request.Request(
        "https://api.github.com" + path,
        headers={
            "Authorization": "Bearer " + os.environ["GITHUB_TOKEN"],
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "promotion-review-only",
        },
    )
    with urllib.request.urlopen(req, timeout=30) as response:
        return json.load(response)


def inspect(repo, number):
    root = "/repos/" + urllib.parse.quote(repo, safe="/")
    pr = fetch_json(root + "/pulls/" + str(number))
    if pr.get("base", {}).get("ref") != "main":
        return {"decision": "hold_invalid", "reason": "Target branch is not main"}
    paths = []
    complete = True
    for page in range(1, 12):
        batch = fetch_json(root + "/pulls/" + str(number) + "/files?per_page=100&page=" + str(page))
        if not isinstance(batch, list):
            complete = False
            break
        if any(not isinstance(item, dict) or not isinstance(item.get("filename"), str) for item in batch):
            complete = False
            break
        paths.extend(item["filename"] for item in batch)
        if len(batch) < 100:
            break
    else:
        complete = False
    if pr.get("changed_files") != len(paths):
        complete = False
    result = classify(paths, draft=bool(pr.get("draft", True)), complete=complete)
    return {
        **result, "pr": number, "head_sha": pr.get("head", {}).get("sha"),
        "files_seen": len(paths), "files_complete": complete,
        "auto_merged": False, "approval_granted": False,
    }


def main():
    repo = os.environ["GITHUB_REPOSITORY"]
    number = int(os.environ["PR_NUMBER"])
    try:
        result = inspect(repo, number)
    except (urllib.error.URLError, ValueError, KeyError, TypeError) as error:
        result = {
            "decision": "hold_incomplete", "reason": "GitHub metadata unavailable: " + type(error).__name__,
            "pr": number, "auto_merged": False, "approval_granted": False,
        }
    output = Path("inventory-output/pr-promotion-review.json")
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    summary = ("### PR promotion review (read-only)\n"
               "- PR: #" + str(number) + "\n"
               "- Decision: **" + result["decision"] + "**\n"
               "- Reason: " + result["reason"] + "\n"
               "- No approval, merge, or deployment performed.\n")
    print(summary)
    with open(os.environ.get("GITHUB_STEP_SUMMARY", os.devnull), "a", encoding="utf-8") as f:
        f.write(summary)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Fail-closed checks before proposing any development ledger change."""
import argparse
import json
from pathlib import Path
try:
    from scripts.development_ledger_proposal import START, END, update
except ModuleNotFoundError:
    from development_ledger_proposal import START, END, update

def verify(original, proposed, report):
    if not isinstance(report, dict) or not isinstance(report.get("snapshot", {}).get("prs"), dict):
        raise ValueError("Missing PR snapshot")
    if not report["snapshot"]["prs"]:
        raise ValueError("Empty PR snapshot: refuse to replace facts")
    expected = update(original, report)
    if proposed != expected:
        raise ValueError("Proposal differs from deterministic generator")
    if update(proposed, report) != proposed:
        raise ValueError("Proposal is not idempotent")
    if proposed.count(START) != 1 or proposed.count(END) != 1:
        raise ValueError("Invalid managed section")
    if len(proposed.encode("utf-8")) > 2_000_000:
        raise ValueError("Oversized ledger proposal")
    return True

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--report", default="inventory-output/report.json")
    parser.add_argument("--ledger", default="docs/DEVELOPMENT_LEDGER.md")
    parser.add_argument("--proposal", default="inventory-output/ledger-proposed.md")
    args = parser.parse_args()
    verify(Path(args.ledger).read_text(encoding="utf-8"),
           Path(args.proposal).read_text(encoding="utf-8"),
           json.loads(Path(args.report).read_text(encoding="utf-8")))

if __name__ == "__main__":
    main()

